<?php
require_once __DIR__.'/includes/letters.php';LetterModule::requireCapability('view');$id=(int)($_GET['id']??$_POST['id']??0);$letter=LetterModule::load($id);if(!$letter||!LetterModule::canViewLetter($letter)){http_response_code(404);$pageTitle='نامه در دسترس نیست';require __DIR__.'/../views/partials/admin-header.php';echo '<section class="card"><h2>نامه در دسترس نیست</h2><p class="muted">نامه وجود ندارد یا مجوز مشاهده آن را ندارید.</p></section>';require __DIR__.'/../views/partials/admin-footer.php';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/letter-view.php?id='.$id);}try{letter_transition($id,(string)($_POST['action']??''));flash('وضعیت نامه به‌روزرسانی شد.');}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Letter transition: '.$e->getMessage());flash('انجام عملیات ممکن نشد.','danger');}redirect('/admin/letter-view.php?id='.$id);}
$attachments=Database::fetchAll('SELECT * FROM organizational_letter_attachments WHERE letter_id=? ORDER BY id',[$id]);$letter['attachment_count']=count($attachments);$logs=Database::fetchAll('SELECT lg.*,u.name user_name FROM organizational_letter_logs lg LEFT JOIN users u ON u.id=lg.user_id WHERE lg.letter_id=? ORDER BY lg.id DESC',[$id]);$pageTitle='مشاهده نامه '.($letter['letter_number']?:'پیش‌نویس');require __DIR__.'/../views/partials/admin-header.php';?>
<div class="letters-page-head"><div><h1><?=e($letter['subject'])?></h1><p><?=e($letter['letter_number']?:'بدون شماره')?> · <?=e(LetterModule::STATUSES[$letter['status']]??$letter['status'])?></p></div><div class="form-actions"><a class="btn" href="/admin/letters.php">بازگشت</a><?php if($letter['status']==='draft'&&LetterModule::can('edit')):?><a class="btn" href="/admin/letter-create.php?id=<?=$id?>">ویرایش</a><?php endif?><a class="btn" target="_blank" href="/admin/letter-print.php?id=<?=$id?>">چاپ</a><a class="btn btn-primary" href="/admin/letter-pdf.php?id=<?=$id?>">PDF</a></div></div>
<div class="letter-view-layout"><section class="letter-preview-shell"><?=letter_document_fragment($letter)?></section><aside class="letter-side-panel"><section class="card"><h2>اطلاعات نامه</h2><dl class="letter-detail-list"><div><dt>وضعیت</dt><dd><span class="letter-badge status-<?=e($letter['status'])?>"><?=e(LetterModule::STATUSES[$letter['status']]??'')?></span></dd></div><div><dt>صادرکننده</dt><dd><?=e($letter['creator_name'])?></dd></div><div><dt>امضاکننده</dt><dd><?=e(($letter['signer_name']?:'—').' '.($letter['signer_title']?:''))?></dd></div><div><dt>اهمیت</dt><dd><?=e(LetterModule::IMPORTANCE[$letter['importance']]??'')?></dd></div><div><dt>محرمانگی</dt><dd><?=e(LetterModule::CONFIDENTIALITY[$letter['confidentiality']]??'')?></dd></div><div><dt>چاپ</dt><dd><?=e($letter['paper_size'].' / '.($letter['orientation']==='portrait'?'عمودی':'افقی'))?></dd></div></dl></section>
<section class="card"><h2>گردش نامه</h2><div class="letter-actions-stack"><?php if($letter['status']==='draft'&&LetterModule::can('edit')):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-primary" name="action" value="request_signature">ارسال برای امضا</button></form><?php endif?><?php if(in_array($letter['status'],['draft','pending_signature'],true)&&LetterModule::can('sign')):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-primary" name="action" value="sign">امضای نامه</button></form><?php endif?><?php if($letter['status']==='signed'&&LetterModule::can('issue')):?><form method="post" onsubmit="return confirm('نامه صادر و در صورت نیاز شماره‌گذاری شود؟')"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-primary" name="action" value="issue">صدور نهایی</button></form><?php endif?><?php if($letter['status']==='issued'&&LetterModule::can('archive')):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn" name="action" value="archive">بایگانی</button></form><?php endif?><?php if(!in_array($letter['status'],['archived','cancelled'],true)&&(LetterModule::can('issue')||(int)$letter['created_by']===(int)Auth::user()['id'])):?><form method="post" onsubmit="return confirm('نامه لغو شود؟')"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-danger" name="action" value="cancel">لغو نامه</button></form><?php endif?></div></section>
<?php if($attachments):?><section class="card"><h2>پیوست‌ها</h2><ul class="letter-attachments"><?php foreach($attachments as $a):?><li><a href="/admin/letter-asset.php?type=attachment&id=<?=$a['id']?>"><?=e($a['original_name'])?></a><small><?=e(number_format($a['file_size']/1024,0))?> KB</small></li><?php endforeach?></ul></section><?php endif?></aside></div>
<section class="card"><h2>تاریخچه نامه</h2><div class="table-wrap"><table><thead><tr><th>زمان</th><th>کاربر</th><th>عملیات</th><th>تغییر وضعیت</th><th>توضیح</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=e(format_jalali_datetime($log['created_at']))?></td><td><?=e($log['user_name']?:'سامانه')?></td><td><?=e(LetterModule::LOG_ACTIONS[$log['action']]??'عملیات سیستمی')?></td><td><?=e(($log['from_status']?LetterModule::STATUSES[$log['from_status']]??'—':'—').' ← '.($log['to_status']?LetterModule::STATUSES[$log['to_status']]??'—':'—'))?></td><td><?=e($log['description']?:'—')?></td></tr><?php endforeach?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
